export const GROUPS = (() => {
  const order = [];
  SECTIONS.forEach((s) => { if (!order.includes(s.group)) order.push(s.group); });
  return order;
})();

export function grouped() {
  return GROUPS.map((g) => ({ group: g, items: SECTIONS.filter((s) => s.group === g) }));
}

export function getSection(id) {
  return SECTIONS.find((s) => s.id === id);
}
